<script setup lang="ts">
import { computed, ref, onMounted, onBeforeUnmount, watch, nextTick } from 'vue'
import { mountChartMotion, type ChartMotion } from './chart-motion'
const dataset=ref('A'),state=ref('ready'),selected=ref(0),root=ref<HTMLElement|null>(null)
let motion:ChartMotion|undefined
onMounted(()=>{if(root.value)motion=mountChartMotion(root.value,'.scusage-card')})
watch([dataset,state],async()=>{await nextTick();motion?.refresh()})
onBeforeUnmount(()=>motion?.destroy())
const labels=['Item 1','Item 2','Item 3','Item 4','Item 5','Item 6'],ticks=[0,25,50,75,100]
const points=computed(()=>{const xs=dataset.value==='A'?[20,28,25,39,33,46]:dataset.value==='B'?[26,19,35,28,43,36]:[0,100,50,50,0,100],ys=dataset.value==='A'?[35,48,41,61,56,74]:dataset.value==='B'?[42,36,55,48,72,64]:[0,100,50,50,100,0];return labels.map((id,i)=>({id,x:xs[i],y:ys[i]}))})
const px=(x:number)=>48+x*2.4,py=(y:number)=>200-y*1.6
function reset(){dataset.value='A';state.value='ready';selected.value=0}
</script>
<template>
<section ref="root" class="scusage-demo" aria-label="Local scatter plot example"><p>Synthetic paired observations. X = preparation units; Y = output units. Both fixed domains are 0–100; every dot has equal size. These are paired measures, not a time series or evidence of causation.</p><div class="scusage-controls"><label>Dataset<select v-model="dataset"><option>A</option><option>B</option><option value="edges">Edges and overlap</option></select></label><label>Data state<select v-model="state"><option value="ready">Ready</option><option value="loading">Loading</option><option value="empty">Empty</option></select></label><button type="button" @click="reset">Reset example</button></div><div class="scusage-card"><template v-if="state==='ready'"><svg viewBox="0 0 330 250" role="img" aria-label="Paired X preparation and Y output on independent fixed zero to one hundred axes; equal radius dots. Exact paired records below."><template v-for="t in ticks" :key="t"><line class="scusage-grid" :x1="px(t)" :x2="px(t)" y1="40" y2="200"/><line class="scusage-grid" x1="48" x2="288" :y1="py(t)" :y2="py(t)"/><text :x="px(t)" y="216" text-anchor="middle">{{ t }}</text><text x="38" :y="py(t)+4" text-anchor="end">{{ t }}</text></template><line class="scusage-axis" x1="48" x2="288" y1="200" y2="200"/><line class="scusage-axis" x1="48" x2="48" y1="40" y2="200"/><text x="48" y="23">Y · output units</text><text x="168" y="240" text-anchor="middle">X · preparation units</text><circle v-for="(p,i) in points" :key="p.id" class="scusage-dot" :class="{selected:selected===i}" :cx="px(p.x)" :cy="py(p.y)" r="5" :data-index="i" data-cm="fade"/></svg><div role="group" aria-label="Select observation" class="scusage-choices"><button v-for="(label,i) in labels" :key="label" type="button" :aria-pressed="selected===i" @focus="selected=i" @click="selected=i">{{ label }}</button></div><p role="status">{{ labels[selected] }}: x {{ points[selected].x }} preparation units; y {{ points[selected].y }} output units. {{ dataset==='edges'&&(selected===2||selected===3)?'Items 3 and 4 share coordinates; both records remain in the table.':'Selection preserves all paired records.' }}</p><table class="scusage-data"><caption>Exact paired observations, dataset {{ dataset }}</caption><thead><tr><th scope="col">Record</th><th scope="col">X</th><th scope="col">Y</th></tr></thead><tbody><tr v-for="p in points" :key="p.id"><th scope="row">{{ p.id }}</th><td>{{ p.x }}</td><td>{{ p.y }}</td></tr></tbody></table><p class="scusage-key">Overlapping points are not missing records. Edges fixture keeps two separate records at (50,50) without jitter or aggregation. Use controls/table to inspect either one. No regression line, correlation or statistical inference is calculated.</p></template><p v-else role="status" class="scusage-state">{{ state==='loading'?'Loading demonstration only; no request is running. Paired records are withheld.':'No observations in this demonstration state. Choose Ready to recover.' }}</p></div></section>
</template>
<style scoped>


.scusage-demo{border:1px solid var(--vp-c-divider);border-radius:14px;padding:18px;margin:20px 0}.scusage-controls{display:flex;gap:14px;flex-wrap:wrap;align-items:end}.scusage-controls label{display:flex;gap:8px;align-items:center;font-size:13px}.scusage-demo select{appearance:auto;padding:8px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg);color:var(--vp-c-text-1)}.scusage-demo button{padding:6px 9px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg-soft)}.scusage-demo :is(button,select):focus-visible{outline:2px solid var(--vp-c-brand-1);outline-offset:3px}.scusage-demo svg{display:block;width:100%;height:auto;max-height:320px;margin:16px 0}.scusage-demo svg text{fill:var(--vp-c-text-2);font-size:11px}.scusage-demo .scusage-total{fill:var(--vp-c-text-1);font-size:24px;font-weight:700}.scusage-choices{display:flex;gap:6px;flex-wrap:wrap}.scusage-choices button[aria-pressed=true]{background:var(--vp-c-brand-soft);font-weight:700}.scusage-choices span{display:inline-block;width:9px;height:9px;border-radius:50%;margin-right:6px}.scusage-data{display:table!important;width:100%;font-size:12px}.scusage-data caption{text-align:left;padding:8px 0;color:var(--vp-c-text-2)}.scusage-data :is(td,th){padding:6px!important}.scusage-state{padding:16px;background:var(--vp-c-bg-soft);border-radius:10px}

.scusage-grid{stroke:var(--vp-c-divider);stroke-dasharray:3 3}.scusage-axis{stroke:var(--vp-c-text-2)}.scusage-dot{fill:var(--vp-c-brand-1);opacity:.65;stroke:var(--vp-c-bg);stroke-width:1}.scusage-dot.selected{fill:var(--vp-c-text-1);opacity:1;stroke:var(--vp-c-brand-1);stroke-width:2}.scusage-key{font-size:12px;color:var(--vp-c-text-2)}
</style>
